import React from 'react';

import clsx from 'clsx';

import { IHikingTransfer } from '@apps/Hiking/@types/hikingTransfers.types';
import PohBadge from '@ui-kit/Badge/Badge';

interface IHikingPrintTransfersProps extends React.HTMLAttributes<HTMLDivElement> {
  transfers: IHikingTransfer[];
}

const HikingPrintTransfers = ({ transfers, className, ...rest }: IHikingPrintTransfersProps) => {
  return (
    <div {...rest} className={clsx(className)}>
      <h3 className="mt-5">Трансферы</h3>
      <table className="table table-bordered table-sm">
        <thead>
          <tr>
            <th>Машина</th>
            <th>Водитель</th>
            <th>Старт</th>
            <th>Финиш</th>

            <th>Пассажиры</th>
          </tr>
        </thead>
        <tbody>
          {transfers.map((tr) => {
            return (
              <tr key={tr.id}>
                <td>
                  {tr.car.name}
                  <br />
                  {tr.car.number}
                  <br />
                  {tr.car.color}
                </td>
                <td>
                  {tr.driver.name}
                  <br />
                  {tr.driver.contacts}
                </td>
                <td>
                  {tr.start.date.toLocaleString()}
                  <br />
                  <small>
                    <em>
                      <small>{tr.start.description}</small>
                    </em>
                  </small>
                </td>
                <td>
                  {tr.finish.date.toLocaleString()}
                  <br />
                  <small>
                    <em>
                      <small>{tr.finish.description}</small>
                    </em>
                  </small>
                </td>

                <td>
                  <ol className="my-0">
                    {tr.members.map((m) => {
                      return (
                        <li key={m.id}>
                          {m.user.name} {m.user.surname}{' '}
                          {m.user.id === tr.driver.user?.id && (
                            <PohBadge as="small">
                              <small>Водитель</small>
                            </PohBadge>
                          )}
                          {m.comment.length > 0 && (
                            <>
                              <br />
                              <small>
                                <em>
                                  <small>{m.comment}</small>
                                </em>
                              </small>
                            </>
                          )}
                        </li>
                      );
                    })}
                  </ol>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

export default HikingPrintTransfers;
