import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { IHikingGpx } from '@apps/Hiking/@types/hiking.types';
import { getRouteThreadItems } from '@apps/Routes/@helpers/route.helper';
import {
  IBaseRouteObjectLine,
  IMapType,
  IRouteObject,
  RouteObjectType,
} from '@apps/Routes/@types/routes.types';
import A4Page from '@components/A4Page';
import PolylineInfo from '@components/PolylineInfo';

const HikingPrintPlanRoutePage = ({
  routeObjects,
  mapType,
  results,
}: {
  routeObjects: IRouteObject[];
  mapType: IMapType;
  results?: IHikingGpx[];
}) => {
  const hikingData = React.useContext(HikingContext);
  if (!hikingData) return 'has no hiking data';

  const routeThread = getRouteThreadItems(routeObjects).join(' — ');

  const linesInDistance = routeObjects.filter(
    (ro) => ro.type === RouteObjectType.Line && ro.is_in_distance,
  ) as IBaseRouteObjectLine[];

  const allThreadsCoordinates = linesInDistance.map((ro) => ro.points);

  return (
    <A4Page>
      <h2>Маршрут</h2>
      <h4>Нитка маршрута</h4>
      <p>{routeThread}</p>
      <PolylineInfo
        points={
          results
            ? (results
                .map((track) => track.track.map(({ point: [la, lo, al] }) => [la, lo, al ?? 0]))
                .flat() as [number, number, number][])
            : allThreadsCoordinates.flat()
        }
        timestamps={
          results
            ? results.map((track) => track.track.map((t) => t.date.getTime())).flat()
            : undefined
        }
        secondaryPoints={
          results ? (allThreadsCoordinates.flat() as [number, number, number][]) : undefined
        }
        mapType={mapType}
        height={600}
        name="Route"
        poi={routeObjects.filter((ro) => ro.type === RouteObjectType.Point)}
      />
    </A4Page>
  );
};

export default HikingPrintPlanRoutePage;
