import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { IDayData } from '@apps/Hiking/@helpers/hikingDays.helper';
import { IHikingGpx } from '@apps/Hiking/@types/hiking.types';
import {
  IBaseRouteObject,
  IBaseRouteObjectLine,
  IRouteObject,
  RouteObjectType,
} from '@apps/Routes/@types/routes.types';
import A4Page from '@components/A4Page';
import { round } from '@helpers/mathHelper';

const HikingPrintPlanRouteDatesPage = ({
  routeObjects,
  daysData,
  results,
}: {
  routeObjects: IRouteObject[];
  daysData: IDayData[];
  results?: IHikingGpx[];
}) => {
  const hikingData = React.useContext(HikingContext);
  if (!hikingData) return 'has no hiking data';

  let totalDist = 0;

  return (
    <A4Page>
      <h2>Общий план прохождения по дням</h2>
      <table className="table table-sm table-condensed table-bordered">
        <thead>
          <tr>
            <th>№пп</th>
            <th>Дата</th>
            <th>План, Участок</th>
            <th>План, км</th>
            {results && (
              <>
                <th>Факт, Участок</th>
                <th>Факт, км</th>
              </>
            )}
          </tr>
        </thead>
        <tbody>
          {daysData
            .filter((dayData) => {
              const isMain =
                dayData.date.getTime() >= hikingData?.start.setHours(0, 0, 0, 0) &&
                dayData.date.getTime() <= hikingData?.finish.setHours(23, 59, 59, 999);
              return isMain;
            })
            .map((dayData, i) => {
              const routeObjs = dayData.schedules
                .filter((sh) => sh.routeObject?.id)
                .reduce<IBaseRouteObject[]>((acc, sh) => {
                  const routeObject = routeObjects.find(
                    (ro) => ro.id === sh.routeObject!.id && ro.is_in_distance,
                  );
                  if (routeObject) {
                    acc.push(routeObject);
                  }

                  return acc;
                }, []);

              const resultsForDate = results?.filter(
                (x) =>
                  x.start.toISOString().substring(0, 10) ===
                  dayData.date.toISOString().substring(0, 10),
              );

              const dist = routeObjs.reduce((s, v) => {
                if (v.type === RouteObjectType.Line)
                  return s + (v as IBaseRouteObjectLine).distance;
                return s;
              }, 0);
              totalDist += dist;

              const planLength = routeObjs.length;
              const factLength = resultsForDate?.length ?? 1;
              const collapsedRow = Math.max(planLength, factLength ?? 1);

              return Array(collapsedRow)
                .fill(null)
                .map((_w, j) => {
                  return (
                    <tr key={dayData.date.toLocaleDateString() + j}>
                      {j === 0 && (
                        <td rowSpan={collapsedRow} className="text-end">
                          {i + 1}
                        </td>
                      )}
                      {j === 0 && (
                        <td rowSpan={collapsedRow} className="text-end">
                          {dayData.date.toLocaleDateString().substr(0, 5)}
                        </td>
                      )}
                      <td>
                        {routeObjs[j] ? (
                          <small>{routeObjs[j].name}</small>
                        ) : (
                          <em className="text-muted">-</em>
                        )}
                      </td>
                      <td className="text-end">
                        {routeObjs[j]
                          ? round((routeObjs[j] as IBaseRouteObjectLine).distance / 1000, 1)
                          : '—'}
                      </td>
                      {results && (
                        <>
                          <td>
                            {resultsForDate?.[j] ? (
                              <small>{resultsForDate[j].name}</small>
                            ) : (
                              <em className="text-muted">-</em>
                            )}
                          </td>
                          <td className="text-end">
                            {resultsForDate?.[j]
                              ? round(resultsForDate[j].distance / 1000, 1)
                              : '-'}
                          </td>
                        </>
                      )}
                    </tr>
                  );
                });
            })}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={3} className="text-end">
              Итого план:
            </td>
            <td className="text-end">{round(totalDist / 1000, 1)}</td>
            {results && (
              <>
                <td className="text-end">Итого факт:</td>
                <td className="text-end">
                  {round(results.reduce((acc, v) => acc + v.distance, 0) / 1000, 1)}
                </td>
              </>
            )}
          </tr>
        </tfoot>
      </table>
    </A4Page>
  );
};

export default HikingPrintPlanRouteDatesPage;
