import React from 'react';

import clsx from 'clsx';

import { IDayData } from '@apps/Hiking/@helpers/hikingDays.helper';
interface IHikingPrintDutyProps extends React.HTMLAttributes<HTMLDivElement> {
  dayData: IDayData;
}

const HikingPrintDuty = ({ dayData, className, ...rest }: IHikingPrintDutyProps) => {
  return (
    <article {...rest} className={clsx(className)}>
      <h3>Дежурят</h3>
      {dayData.duty.map((duty) => {
        return (
          <li key={duty.id}>
            {duty.user.name}
            {duty.comment.length > 0 && (
              <>
                {' • '}
                <em>
                  <small className="text-warning">{duty.comment}</small>
                </em>
              </>
            )}
          </li>
        );
      })}
    </article>
  );
};

export default HikingPrintDuty;
