import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import A4Page from '@components/A4Page';
import PohAva from '@ui-kit/Ava';

const HikingPrintMembersPage = () => {
  const hikingData = React.useContext(HikingContext);
  if (!hikingData) return 'has no hiking data';

  return (
    <A4Page>
      <h2>Участники</h2>
      <table className="table table-sm table-condensed table-bordered">
        <thead>
          <tr>
            <th>№пп</th>
            <th>Фото</th>
            <th>Имя</th>
            <th>Должность</th>
            <th>Примечание</th>
          </tr>
        </thead>
        <tbody>
          {hikingData.hikers.map((hiker, i) => (
            <tr key={hiker.idUser}>
              <td className="text-end">{i + 1}</td>
              <td>
                <PohAva
                  src={hiker.photo['100']}
                  style={{ float: 'right', clear: 'inline-end' }}
                  width={50}
                  alt={`${hiker.name} ${hiker.surname}`}
                />
              </td>
              <td>
                <strong>
                  {hiker.name} {hiker.surname}
                </strong>
                <small className="d-block text-muted">
                  Подтвердил{hiker.isGirl ? 'а' : ''} свое участие в походе{' '}
                  {hiker.date.toLocaleString()}
                </small>
              </td>

              <td>
                {hiker.positions?.length > 0 && (
                  <small>
                    {hiker.positions.map((pos) => (
                      <div key={pos.id}>
                        {pos.name}{' '}
                        {pos.comment.length > 0 && (
                          <>
                            {' '}
                            • <em>{pos.comment}</em>
                          </>
                        )}
                      </div>
                    ))}
                  </small>
                )}
              </td>
              <td>
                {(hiker.dateFrom || hiker.dateTo) && (
                  <small className="text-danger">
                    Неполное участие в походе: c{' '}
                    {hiker.dateFrom ? hiker.dateFrom.toLocaleString() : 'начала'} до{' '}
                    {hiker.dateTo ? hiker.dateTo.toLocaleString() : 'конца'}
                  </small>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </A4Page>
  );
};

export default HikingPrintMembersPage;
