import React from 'react';

import ArrowBarUp from '@pohodnik/icons/svg/Arrows/ArrowBarUp';
import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import clsx from 'clsx';

import { IDayData } from '@apps/Hiking/@helpers/hikingDays.helper';
import { formattedLocaleTime } from '@helpers/dateHelper';
import { formatAltitude, formatDistance, formatFinance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';

interface IHHikingPrintScheduleProps extends React.HTMLAttributes<HTMLDivElement> {
  dayData: IDayData;
}

const HikingPrintSchedule = ({ dayData, className, ...rest }: IHHikingPrintScheduleProps) => {
  return (
    <article {...rest} className={clsx(className)}>
      <h3>Расписание</h3>
      {dayData.schedules.map((sh) => {
        return (
          <li key={sh.id} className="text-nowrap text-truncate">
            <code>
              {dayData.date.toLocaleDateString() !== sh.start.toLocaleDateString() &&
                sh.start.toLocaleDateString() + '\u00a0'}
              {formattedLocaleTime(sh.start)}
              {` - `}
              {dayData.date.toLocaleDateString() !== sh.finish.toLocaleDateString() &&
                sh.finish.toLocaleDateString() + '\u00a0'}
              {formattedLocaleTime(sh.finish)}
            </code>
            &nbsp; &nbsp;
            {sh.name}
            &nbsp; &nbsp;
            {sh.routeObject && (
              <strong className="text-danger">
                <small>{formatDistance(sh.routeObject.distance ?? 0)}</small> &nbsp;{' '}
              </strong>
            )}
            {sh.description && (
              <em>
                <small>{sh.description}</small> &nbsp;{' '}
              </em>
            )}
            {sh.cost && (
              <abbr>
                <small>~{formatFinance(sh.cost)}</small> &nbsp;{' '}
              </abbr>
            )}
            {sh.link && (
              <span>
                <small>
                  <a href={sh.link}>[ссылка]</a>
                </small>{' '}
                &nbsp;{' '}
              </span>
            )}
            {sh.routeObject && sh.routeObject.coordinates && (
              <span>
                <small>
                  <GeoAlt />
                  &nbsp;
                  <a href={`geo:${sh.routeObject.coordinates.slice(0, 2)}`}>
                    {sh.routeObject.coordinates
                      .slice(0, 2)
                      .map((x) => round(x!, 5))
                      .join(', ')}
                  </a>{' '}
                  &nbsp;{' '}
                  {sh.routeObject.coordinates[2] && (
                    <>
                      <ArrowBarUp />
                      {formatAltitude(sh.routeObject.coordinates[2])}
                    </>
                  )}{' '}
                </small>{' '}
                &nbsp;{' '}
              </span>
            )}
          </li>
        );
      })}
    </article>
  );
};

export default HikingPrintSchedule;
