import React from 'react';

import clsx from 'clsx';

import { IDayData } from '@apps/Hiking/@helpers/hikingDays.helper';
import { getShortName } from '@apps/Hiking/menu/components/HikingMenu/helper';
import { round } from '@helpers/mathHelper';

import styles from '../styles.module.less';

interface IHikingPrintUsersLoadProps extends React.HTMLAttributes<HTMLDivElement> {
  dayData: IDayData;
}

const HikingPrintUsersLoad = ({ dayData, className, ...rest }: IHikingPrintUsersLoadProps) => {
  return (
    <article {...rest} className={clsx(className)}>
      <h3 className="mt-3">Загрузка</h3>
      <table className={clsx('table table-sm table-condensed table-bordered', styles.noBreak)}>
        <tbody>
          <tr>
            {dayData.userLoad.map((h) => {
              return (
                <th key={h.hiker.idUser}>
                  {getShortName([h.hiker.surname, h.hiker.name].join(' '), 1)}
                </th>
              );
            })}
          </tr>
          <tr>
            {dayData.userLoad.map((h) => {
              return (
                <td key={h.hiker.idUser} title={`${h.kg}`}>
                  {round(h.kg, 1)}
                  <small>&thinsp;кг.</small>
                  <small className="float-end text-muted" title={`${h.pct}`}>
                    {round(h.pct, 0)}
                    <small>&thinsp;%</small>
                  </small>
                </td>
              );
            })}
          </tr>
        </tbody>
      </table>
    </article>
  );
};

export default HikingPrintUsersLoad;
